    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option_symbol = self.add_option("SPY", Resolution.MINUTE).symbol
        self.option_symbol.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(timedelta(days=0), timedelta(days=365))
        )

        self._five_minute_closes = deque(maxlen=20)
        self._bucket_end = None
        self._bucket_bars = []
        self._bucket_valid = True
        self._expected_minute_end = None

        self._entry_order_id = None
        self._exit_order_id = None
        self._held_option = None
        self._entry_fill_price = None
        self._no_entry_date = None
        self._equity_liquidation_order_id = None

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self._held_option is not None:
            if not self.portfolio[self._held_option].invested:
                self._clear_option_state()
            else:
                self._evaluate_option_exit(data)

        spy_bar = data.bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bars(spy_bar, data)

    def _update_five_minute_bars(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.end_time
        clock = end_time.time()

        if clock < time(9, 31) or clock > time(16, 0):
            return

        bucket_end = end_time.replace(
            minute=((end_time.minute // 5) + (0 if end_time.minute % 5 == 0 else 1)) * 5,
            second=0,
            microsecond=0
        )

        # Handle hour rollover, e.g. 09:59 -> 10:00.
        if bucket_end.minute == 60:
            bucket_end = bucket_end.replace(minute=0) + timedelta(hours=1)

        if self._bucket_end is None or bucket_end != self._bucket_end:
            self._bucket_end = bucket_end
            self._bucket_bars = []
            self._bucket_valid = True
            self._expected_minute_end = bucket_end - timedelta(minutes=4)

        if end_time != self._expected_minute_end:
            self._bucket_valid = False

        self._bucket_bars.append(minute_bar)
        self._expected_minute_end = end_time + timedelta(minutes=1)

        if end_time != self._bucket_end:
            return

        if self._bucket_valid and len(self._bucket_bars) == 5:
            bars = self._bucket_bars
            five_minute_bar = TradeBar(
                bars[0].time,
                self.spy,
                bars[0].open,
                max(x.high for x in bars),
                min(x.low for x in bars),
                bars[-1].close,
                sum(x.volume for x in bars),
                timedelta(minutes=5)
            )
            self._on_five_minute_bar(five_minute_bar, data)

        self._bucket_end = None
        self._bucket_bars = []
        self._bucket_valid = True
        self._expected_minute_end = None

    def _on_five_minute_bar(self, bar: TradeBar, data: Slice):
        had_ready_averages = len(self._five_minute_closes) == 20

        if had_ready_averages:
            previous_fast = sum(list(self._five_minute_closes)[-5:]) / 5.0
            previous_slow = sum(self._five_minute_closes) / 20.0

        self._five_minute_closes.append(bar.close)

        if not had_ready_averages:
            return

        current_fast = sum(list(self._five_minute_closes)[-5:]) / 5.0
        current_slow = sum(self._five_minute_closes) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar.end_time.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_call(data, bar.close)

    def _try_enter_call(self, data: Slice, spy_price: float):
        if self._no_entry_date == self.time.date():
            return

        if self._held_option is not None and self.portfolio[self._held_option].invested:
            return

        if self._entry_order_is_open():
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in current Slice.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.debug("Entry skipped: no eligible SPY call expiration.")
            return

        selected_expiry = min(contract.expiry.date() for contract in calls)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in calls
            if contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no call strike at least 1% OTM.")
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        ticket = self.market_order(selected.symbol, 1)

        self._entry_order_id = ticket.order_id
        self.debug(
            f"Entry submitted: {selected.symbol}, expiry {selected.expiry.date()}, "
            f"strike {selected.strike:.2f}."
        )

    def _evaluate_option_exit(self, data: Slice):
        if self._exit_order_is_open():
            return

        contract = self._find_contract_in_slice(data, self._held_option)
        if contract is not None:
            bid = contract.bid_price
            ask = contract.ask_price

            if bid is not None and ask is not None and bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self._entry_fill_price * 1.50:
                    self._submit_option_exit("profit target")
                    return

        expiry_date = self._held_option.id.date.date()
        prior_trading_day = self.securities[self.spy].exchange.hours.get_previous_trading_day(
            datetime.combine(expiry_date, time.min)
        ).date()

        if self.time.date() == prior_trading_day and self.time.time() == time(15, 45):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _handle_expiration_processing(self):
        if self._held_option is None or not self.portfolio[self._held_option].invested:
            return

        expiry_date = self._held_option.id.date.date()
        if self.time.date() >= expiry_date:
            self._no_entry_date = self.time.date()
            self.debug(
                f"Expiration handling: liquidating remaining {self._held_option}."
            )
            self._submit_option_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        if not self.portfolio[self.spy].invested:
            self._equity_liquidation_order_id = None
            return

        if self._equity_liquidation_order_id is not None:
            order = self.transactions.get_order_by_id(self._equity_liquidation_order_id)
            if order is not None and order.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return

        quantity = self.portfolio[self.spy].quantity
        ticket = self.market_order(self.spy, -quantity)
        self._equity_liquidation_order_id = ticket.order_id
        self.debug("Unexpected SPY exercise/assignment position detected; liquidating SPY.")

    def _submit_option_exit(self, reason: str):
        if self._held_option is None or not self.portfolio[self._held_option].invested:
            return

        if self._exit_order_is_open():
            return

        for order in self.transactions.get_open_orders(self._held_option):
            self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self._held_option].quantity
        ticket = self.market_order(self._held_option, -quantity)
        self._exit_order_id = ticket.order_id
        self.debug(f"Exit submitted for {self._held_option}: {reason}.")

    def _find_contract_in_slice(self, data: Slice, symbol: Symbol):
        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.symbol == symbol:
                return contract

        return None

    def _entry_order_is_open(self):
        if self._entry_order_id is None:
            return False

        order = self.transactions.get_order_by_id(self._entry_order_id)
        return order is not None and order.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _exit_order_is_open(self):
        if self._exit_order_id is None:
            return False

        order = self.transactions.get_order_by_id(self._exit_order_id)
        return order is not None and order.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _clear_option_state(self):
        self._held_option = None
        self._entry_fill_price = None
        self._entry_order_id = None
        self._exit_order_id = None

    def on_order_event(self, order_event: OrderEvent):
