        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-1000, 1000).Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute)

        self.pending_entry_bar_end = None
        self.entry_ticket = None
        self.exit_tickets = []

        self.held_contract = None
        self.entry_fill_price = None
        self.expiration_block_date = None

    def OnFiveMinuteBar(self, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        self.pending_entry_bar_end = None

        if previous_fast is None or previous_slow is None or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_time = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.HasOpenOptionPosition():
            self.HandleExpirationProtection()
            self.HandleTimeStop()
            self.HandleProfitTarget(data)

        if self.pending_entry_bar_end == self.Time:
            self.pending_entry_bar_end = None
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.HasOpenOptionPosition() or self.HasOpenEntryOrder() or self.HasOpenExitOrder():
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"Skipped entry {self.Time}: no current SPY price")
            return

        chain = self.GetOptionChain(data)
        if chain is None:
            self.Debug(f"Skipped entry {self.Time}: no option chain")
            return

        eligible_date = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= eligible_date
        ]

        if not calls:
            self.Debug(f"Skipped entry {self.Time}: no eligible call expiration")
            return

        expiry = min(contract.Expiry.date() for contract in calls)
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == expiry and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"Skipped entry {self.Time}: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted {self.Time}: {selected.Symbol}, "
            f"strike={selected.Strike}, expiry={selected.Expiry.date()}"
        )

    def HandleProfitTarget(self, data):
        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
