            if self.Portfolio[self.held_contract].Quantity > 0:
                self.SubmitExit("expiration safety liquidation")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position ({spy_quantity}) from exercise/assignment; liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        self.CancelOtherOpenExitOrders()
        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted for {self.held_contract}: {reason}.")

    def CancelOtherOpenExitOrders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders():
            if order.Symbol == self.held_contract:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order.")

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status in [OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled]

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order {order_event.OrderId} did not fill: {order_event.Status}.")
                self.entry_order_id = None

        elif order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.held_contract = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
